DO $grant$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='notification_runtime') THEN
    GRANT SELECT,INSERT,UPDATE,DELETE ON fixed_window_limits,delivery_dead_letters TO notification_runtime;
  END IF;
END $grant$;

CREATE FUNCTION register_delivery_identity() RETURNS trigger LANGUAGE plpgsql AS $body$
BEGIN
 INSERT INTO delivery_identities(id,tenant_id,event_id,subscription_id)
 VALUES(NEW.id,NEW.tenant_id,NEW.event_id,NEW.subscription_id) ON CONFLICT DO NOTHING;
 IF NOT FOUND THEN RETURN NULL; END IF;
 RETURN NEW;
END $body$;

DO $grant$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='notification_runtime') THEN
  GRANT SELECT,INSERT,UPDATE,DELETE ON subscription_versions,delivery_identities,delivery_history TO notification_runtime;
  GRANT SELECT ON all_deliveries TO notification_runtime;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='notification_backup') THEN
  GRANT SELECT ON subscription_versions,delivery_identities,delivery_history TO notification_backup;
 END IF;
END $grant$;
